# Build the mod's text from localization/localization.<culture>.csv:
#  - LOC_MolotovText: the Zone Kit Text Tool asset (editor-only; what the GUI shows)
#  - Autogenerated_<n>_LocalizationDatabase: what the game reads. Its
#    ModLocalizationManager merges every mod's *_LocalizationDatabase over vanilla
#    text, so the mod never ships (or goes stale against) a copy of Game.locres.
# The GUI's "Package mod" generates the database from the Text Tool asset, but
# the headless UAT cook only builds it in memory, so it is written here too
# (same name pattern, so a later GUI package replaces it cleanly).
# Neither class nor their row structs are exposed to Python, and their fields are
# read-only to it: rows are made with Array.resize()/Map.setdefault() and filled
# through reflection or import_text.
# Run via editor_headless_all.py.
import csv
import glob
import os
import re
import time

import unreal

PLUGIN = "/MolotovBottle"
ASSET = "LOC_MolotovText"
DB_PATTERN = re.compile(r"^Autogenerated_\d+_LocalizationDatabase$")
LOC_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "localization"
)
L = unreal.LocalizationLanguage
CULTURES = {
    "en": L.ENGLISH, "uk": L.UKRAINIAN, "de": L.GERMAN, "fr": L.FRENCH,
    "es": L.SPANISH_EUROPEAN, "it": L.ITALIAN, "pl": L.POLISH, "cs": L.CZECH,
    "tr": L.TURKISH, "sr": L.SERBIAN, "pt-BR": L.PORTUGAL_BRAZILIAN,
    "es-419": L.SPANISH_LATINO_AMERICAN, "ar": L.ARABIC,
    "zh-Hans": L.CHINESE_SIMPLIFIED, "zh-Hant": L.CHINESE_TRADITIONAL,
    "ja": L.JAPANESE, "ko": L.KOREAN, "ru": L.RUSSIAN,
}

texts = {}  # key -> {LocalizationLanguage: text}
keys_by_culture = {}

for path in sorted(glob.glob(os.path.join(LOC_DIR, "localization.*.csv"))):
    culture = os.path.basename(path)[len("localization."):-len(".csv")]
    assert culture in CULTURES, f"unknown culture '{culture}' in {path}"

    with open(path, encoding="utf-8-sig", newline="") as csv_file:
        for row in csv.DictReader(csv_file):
            texts.setdefault(row["key"], {})[CULTURES[culture]] = row["text"]
            keys_by_culture.setdefault(culture, set()).add(row["key"])

assert texts, f"no localization rows found in {LOC_DIR}"

# a key missing from one language would show its raw SID there, not English
for culture, keys in sorted(keys_by_culture.items()):
    assert keys == set(texts), (
        f"localization.{culture}.csv must cover every key; "
        f"missing {sorted(set(texts) - keys)}"
    )

path = f"{PLUGIN}/{ASSET}"
# reuse the existing asset: its package name is the mod's localization identity
asset = unreal.EditorAssetLibrary.load_asset(path)
if not asset:
    asset = unreal.AssetToolsHelpers.get_asset_tools().create_asset(
        ASSET, PLUGIN, None, unreal.LocalizationModTextToolAssetFactory()
    )
assert asset, f"could not create {path}"

rows = asset.get_editor_property("LocalizedTexts")
rows.resize(0)
rows.resize(len(texts))
for i, (key, langs) in enumerate(sorted(texts.items())):
    row = rows[i]
    row.set_editor_property("SID", key)
    strings = row.get_editor_property("LanguagesToLocalizedStrings")
    strings.clear()
    for lang, text in langs.items():
        strings[lang] = text
    row.set_editor_property("LanguagesToLocalizedStrings", strings)
    rows[i] = row
asset.set_editor_property("LocalizedTexts", rows)

for row in asset.get_editor_property("LocalizedTexts"):
    unreal.log(f"TEXT_ROW {row.export_text()}")
saved = unreal.EditorAssetLibrary.save_asset(path, only_if_is_dirty=False)

# one database per mod: reuse its name (the mod's identity once cooked), drop extras
dbs = sorted(
    p.split(".")[0]
    for p in unreal.EditorAssetLibrary.list_assets(PLUGIN, recursive=False)
    if DB_PATTERN.match(p.split(".")[0].rsplit("/", 1)[-1])
)
for extra in dbs[1:]:
    unreal.EditorAssetLibrary.delete_asset(extra)
    unreal.log(f"TEXT_DB removed duplicate {extra}")
if dbs:
    db_path = dbs[0]
    db = unreal.EditorAssetLibrary.load_asset(db_path)
else:
    db_name = f"Autogenerated_{int(time.time())}_LocalizationDatabase"
    db_path = f"{PLUGIN}/{db_name}"
    factory = unreal.DataAssetFactory()
    factory.set_editor_property(
        "data_asset_class",
        unreal.load_class(None, "/Script/Stalker2.ModLocalizationDatabaseDataAsset"),
    )
    db = unreal.AssetToolsHelpers.get_asset_tools().create_asset(
        db_name, PLUGIN, None, factory
    )
assert db, f"could not create {db_path}"

db.modify()
# read-only to set_editor_property, but the wrapper edits the asset's map in place
entries = db.get_editor_property("LocalizationDatabase")
entries.clear()
for row in asset.get_editor_property("LocalizedTexts"):
    # both structs share the LanguagesToLocalizedStrings field: copy it as text
    exported = row.export_text()
    value = entries.setdefault(row.get_editor_property("SID"))
    value.import_text("(" + exported[exported.index("LanguagesToLocalizedStrings="):])
    entries[row.get_editor_property("SID")] = value

written = db.get_editor_property("LocalizationDatabase")
for key, langs in sorted(texts.items()):
    got = written[key].get_editor_property("LanguagesToLocalizedStrings")
    assert dict(got.items()) == langs, f"database mismatch for {key}: {written[key].export_text()}"
db_saved = unreal.EditorAssetLibrary.save_asset(db_path, only_if_is_dirty=False)
unreal.log(f"TEXT_DB {db_path} entries={len(written)} saved={db_saved}")
saved = saved and db_saved
unreal.log(f"TEXT_IMPORT_DONE saved={saved} rows={len(texts)}")
